-- Acceptance tests for migration 27. DISPOSABLE DATABASE ONLY (name must end in _Tests).
--   sqlcmd -S localhost -E -C -b -d GameOn_Tests -i database\28-clubs-community-tests.sql
SET NOCOUNT ON; SET XACT_ABORT OFF; SET QUOTED_IDENTIFIER ON; SET ANSI_NULLS ON;
IF DB_NAME() NOT LIKE N'%[_]Tests' THROW 50002,'Run these tests only on a disposable *_Tests database.',1;
IF NOT EXISTS(SELECT 1 FROM dbo.PlatformMigrations WHERE Version=27) THROW 50002,'Apply migration 27 to this test database first.',1;
DECLARE @tag nvarchar(12)=LEFT(REPLACE(CONVERT(nvarchar(36),NEWID()),'-',''),10);
DECLARE @t TABLE(Name nvarchar(200),Pass bit);
DECLARE @one TABLE(a sql_variant);
DECLARE @row TABLE(a sql_variant,b sql_variant,c sql_variant,d sql_variant,e sql_variant,f sql_variant,g sql_variant,h sql_variant);
DECLARE @ok bit,@Op int,@Own int,@Mgr int,@P1 int,@P2 int,@Out int,@V int,@Club int,@Court int,@B1 bigint,@B2 bigint,@k uniqueidentifier,@Code char(10),@G int,@Conv bigint,@Rev int;
DECLARE @Sport int=(SELECT TOP(1) SubtypeId FROM dbo.Subtypes WHERE Slug='padel');
DECLARE @Today date=CAST(SYSUTCDATETIME() AS date);
DECLARE @Day date=CAST(DATEADD(day,2,dbo.ToBeirut(SYSUTCDATETIME())) AS date);
DECLARE @Ten datetime2(0)=dbo.FromBeirut(DATEADD(hour,10,CAST(@Day AS datetime2(0)))),@Seven datetime2(0)=dbo.FromBeirut(DATEADD(hour,19,CAST(@Day AS datetime2(0))));
DECLARE @Odd datetime2(0)=DATEADD(minute,15,@Ten),@future datetime2(3)=DATEADD(day,3,SYSUTCDATETIME());
INSERT dbo.Users(Email,DisplayName,PasswordHash) VALUES('op'+@tag+'@gameon.invalid','Op','x'); SET @Op=SCOPE_IDENTITY();
INSERT dbo.Users(Email,DisplayName,PasswordHash) VALUES('own'+@tag+'@gameon.invalid','Owner','x'); SET @Own=SCOPE_IDENTITY();
INSERT dbo.Users(Email,DisplayName,PasswordHash) VALUES('mgr'+@tag+'@gameon.invalid','Manager','x'); SET @Mgr=SCOPE_IDENTITY();
INSERT dbo.Users(Email,DisplayName,PasswordHash) VALUES('p1'+@tag+'@gameon.invalid','Player One','x'); SET @P1=SCOPE_IDENTITY();
INSERT dbo.Users(Email,DisplayName,PasswordHash) VALUES('p2'+@tag+'@gameon.invalid','Player Two','x'); SET @P2=SCOPE_IDENTITY();
INSERT dbo.Users(Email,DisplayName,PasswordHash) VALUES('out'+@tag+'@gameon.invalid','Outsider','x'); SET @Out=SCOPE_IDENTITY();
INSERT dbo.PaymentOperators(UserId) VALUES(@Op);
INSERT dbo.Venues(Name,Area,Address,ListingStatus) VALUES(N'Club venue '+@tag,N'Jounieh',N'Seaside road','Unverified'); SET @V=SCOPE_IDENTITY();
-- Clubs & roles
SET @ok=0; BEGIN TRY EXEC dbo.CreateClub @OperatorId=@P1,@VenueId=@V,@Name=N'X',@OwnerUserId=@P1; END TRY BEGIN CATCH SET @ok=IIF(ERROR_NUMBER()=50003,1,0); END CATCH;
INSERT @t VALUES('Only operators onboard clubs',@ok);
INSERT @one EXEC dbo.CreateClub @OperatorId=@Op,@VenueId=@V,@Name=N'Test Padel Club',@OwnerUserId=@Own,@IsPartner=1,@ProDiscountPct=20; SELECT @Club=CONVERT(int,a) FROM @one; DELETE @one;
INSERT @one EXEC dbo.SetClubStaff @ClubId=@Club,@ActorId=@Own,@UserId=@Mgr,@Role='Manager'; DELETE @one;
SET @ok=0; BEGIN TRY EXEC dbo.SetClubStaff @ClubId=@Club,@ActorId=@Mgr,@UserId=@P1,@Role='Manager'; END TRY BEGIN CATCH SET @ok=IIF(ERROR_NUMBER()=50003,1,0); END CATCH;
INSERT @t VALUES('Only owner manages staff',@ok);
SET @ok=0; BEGIN TRY EXEC dbo.SaveCourt @ClubId=@Club,@ActorId=@P1,@Name=N'C',@SubtypeId=@Sport,@SlotMinutes=60,@OpenHour=8,@CloseHour=23,@BasePrice=20,@PeakPrice=30,@PeakStartHour=18,@PeakEndHour=22; END TRY BEGIN CATCH SET @ok=IIF(ERROR_NUMBER()=50003,1,0); END CATCH;
INSERT @t VALUES('Players cannot edit courts',@ok);
INSERT @one EXEC dbo.SaveCourt @ClubId=@Club,@ActorId=@Mgr,@Name=N'Court 1',@SubtypeId=@Sport,@SlotMinutes=60,@OpenHour=8,@CloseHour=23,@BasePrice=20,@PeakPrice=30,@PeakStartHour=18,@PeakEndHour=22; SELECT @Court=CONVERT(int,a) FROM @one; DELETE @one;
-- Schedule & pricing
DECLARE @sched TABLE(CourtId int,Court nvarchar(80),SubtypeId int,LocalStart datetime2(0),LocalEnd datetime2(0),StartsAtUtc datetime2(0),IsPeak bit,ListPrice decimal(10,2),ProPct int,SlotStatus varchar(10),BookedBy nvarchar(80),BookingId bigint,BlockId bigint,BlockReason nvarchar(120));
DECLARE @cls TABLE(a sql_variant,b sql_variant,c sql_variant,d sql_variant,e sql_variant,f sql_variant,g sql_variant,h sql_variant,i sql_variant,j sql_variant,k sql_variant);
INSERT @sched EXEC dbo.GetCourtSchedule @ClubId=@Club,@Day=@Day,@UserId=@P1,@IncludeClasses=0;
INSERT @t SELECT 'Schedule lists 15 hourly slots 08:00-23:00',IIF((SELECT COUNT(*) FROM @sched)=15,1,0);
INSERT @t SELECT 'Peak price at 19:00, base price at 10:00',IIF((SELECT ListPrice FROM @sched WHERE StartsAtUtc=@Seven)=30 AND (SELECT ListPrice FROM @sched WHERE StartsAtUtc=@Ten)=20,1,0);
DELETE @sched;
-- Booking, idempotency, double booking, alignment
SET @k=NEWID();
INSERT @row(a,b,c,d,e,f,g,h) EXEC dbo.BookCourt @CourtId=@Court,@UserId=@P1,@StartsAtUtc=@Ten,@Key=@k; SELECT @B1=CONVERT(bigint,a) FROM @row; DELETE @row;
INSERT @row(a,b,c,d,e,f,g,h) EXEC dbo.BookCourt @CourtId=@Court,@UserId=@P1,@StartsAtUtc=@Ten,@Key=@k; DELETE @row;
INSERT @t SELECT 'Retried booking request creates one booking',IIF((SELECT COUNT(*) FROM dbo.CourtBookings WHERE CourtId=@Court)=1,1,0);
SET @ok=0; BEGIN TRY EXEC dbo.BookCourt @CourtId=@Court,@UserId=@P2,@StartsAtUtc=@Ten,@Key=@k; END TRY BEGIN CATCH SET @ok=IIF(ERROR_NUMBER()=50004,1,0); END CATCH;
INSERT @t VALUES('Same slot cannot be booked twice',@ok);
SET @ok=0; BEGIN TRY DECLARE @k2 uniqueidentifier=NEWID(); EXEC dbo.BookCourt @CourtId=@Court,@UserId=@P2,@StartsAtUtc=@Odd,@Key=@k2; END TRY BEGIN CATCH SET @ok=IIF(ERROR_NUMBER()=50002,1,0); END CATCH;
INSERT @t VALUES('Misaligned or overlapping time refused',@ok);
INSERT @t SELECT 'Booking earns 20 points',IIF((SELECT Points FROM dbo.LoyaltyAccounts WHERE UserId=@P1)=20,1,0);
INSERT @sched EXEC dbo.GetCourtSchedule @ClubId=@Club,@Day=@Day,@UserId=@P2,@IncludeClasses=0;
INSERT @t SELECT 'Other players see Booked without the booker name',IIF((SELECT SlotStatus FROM @sched WHERE StartsAtUtc=@Ten)='Booked' AND (SELECT BookedBy FROM @sched WHERE StartsAtUtc=@Ten) IS NULL,1,0); DELETE @sched;
INSERT @sched EXEC dbo.GetCourtSchedule @ClubId=@Club,@Day=@Day,@UserId=@Mgr,@IncludeClasses=0;
INSERT @t SELECT 'Staff see who booked',IIF((SELECT BookedBy FROM @sched WHERE StartsAtUtc=@Ten)='Player One',1,0); DELETE @sched;
-- Blocks (2-tap toggle)
SET @ok=0; BEGIN TRY EXEC dbo.ToggleCourtBlock @CourtId=@Court,@ActorId=@Mgr,@StartsAtUtc=@Ten; END TRY BEGIN CATCH SET @ok=IIF(ERROR_NUMBER()=50004,1,0); END CATCH;
