INSERT @one EXEC dbo.ToggleCourtBlock @CourtId=@Court,@ActorId=@Mgr,@StartsAtUtc=@Eleven,@Reason=N'Maintenance'; DELETE @one;
SET @ok=0; SET @k=NEWID(); BEGIN TRY EXEC dbo.BookCourt @CourtId=@Court,@UserId=@P2,@StartsAtUtc=@Eleven,@Key=@k; END TRY BEGIN CATCH SET @ok=IIF(ERROR_NUMBER()=50004,1,0); END CATCH;
INSERT @t VALUES('Blocked slot cannot be booked',@ok);
INSERT @one EXEC dbo.ToggleCourtBlock @CourtId=@Court,@ActorId=@Mgr,@StartsAtUtc=@Eleven; DELETE @one;
INSERT @t SELECT 'Second tap unblocks',IIF(NOT EXISTS(SELECT 1 FROM dbo.CourtBlocks WHERE CourtId=@Court),1,0);
SET @ok=0; BEGIN TRY EXEC dbo.ToggleCourtBlock @CourtId=@Court,@ActorId=@P2,@StartsAtUtc=@Eleven; END TRY BEGIN CATCH SET @ok=IIF(ERROR_NUMBER()=50003,1,0); END CATCH;
INSERT @t VALUES('Players cannot block courts',@ok);
-- Cancellation reverses exactly the earned points
SET @ok=0; BEGIN TRY EXEC dbo.CancelCourtBooking @BookingId=@B1,@UserId=@P2; END TRY BEGIN CATCH SET @ok=IIF(ERROR_NUMBER()=50003,1,0); END CATCH;
INSERT @t VALUES('Cannot cancel someone else''s booking',@ok);
INSERT @one EXEC dbo.CancelCourtBooking @BookingId=@B1,@UserId=@P1; DELETE @one;
INSERT @t SELECT 'Cancel frees slot and reverses points',IIF((SELECT Status FROM dbo.CourtBookings WHERE BookingId=@B1)='Cancelled' AND (SELECT Points FROM dbo.LoyaltyAccounts WHERE UserId=@P1)=0,1,0);
-- Pro membership via wallet, partner discount
DECLARE @Top uniqueidentifier,@ref nvarchar(40)=N'PRO-'+@tag;
SET @k=NEWID(); INSERT @row(a,b,c,d,e,f) EXEC dbo.CreateTopUp @UserId=@P1,@Key=@k,@Amount=20,@Recipient='+96171364432'; SELECT @Top=CONVERT(uniqueidentifier,a) FROM @row; DELETE @row;
