SET @k=NEWID(); INSERT @row(a,b,c,d,e,f,g,h) EXEC dbo.BookCourt @CourtId=@Court,@UserId=@P1,@StartsAtUtc=@Noon,@Key=@k,@RedemptionCode=@Code; SELECT @B3=CONVERT(bigint,a) FROM @row; DELETE @row;
