SET @ok=0; SET @k=NEWID(); BEGIN TRY EXEC dbo.BookCourt @CourtId=@Court,@UserId=@P1,@StartsAtUtc=@OnePm,@Key=@k,@RedemptionCode=@Code; END TRY BEGIN CATCH SET @ok=1; END CATCH;
